mapper.insert:
insert into execution_plan (
    id, project_id, name, status, environment_key, trigger_policy_json, dag_digest,
    description, created_by, updated_by, archived_at, created_at, updated_at
) values (
    #{id}, #{projectId}, #{name}, #{status}, #{environmentKey},
    cast(coalesce(#{triggerPolicyJson}, '{}') as jsonb),
    #{dagDigest}, #{description}, #{createdBy}, #{updatedBy}, #{archivedAt}, #{createdAt}, #{updatedAt}
)

insert into execution_run (
    id, plan_id, project_id, status, trigger_type, request_key, source_event_id, attempt, trace_id,
    result_summary_json, error_code, error_summary, created_by, started_at, finished_at, created_at, updated_at
) values (
    #{id}, #{planId}, #{projectId}, #{status}, #{triggerType}, #{requestKey}, #{sourceEventId},
    #{attempt}, #{traceId}, cast(coalesce(#{resultSummaryJson}, '{}') as jsonb),
    #{errorCode}, #{errorSummary}, #{createdBy}, #{startedAt}, #{finishedAt}, #{createdAt}, #{updatedAt}
)
on conflict do nothing

insert into execution_node_run (
    id, run_id, plan_node_id, status, attempt, runner_type, external_run_id, error_code, error_summary,
    result_summary_json, heartbeat_at, queued_at, started_at, finished_at, created_at, updated_at
) values (
    #{id}, #{runId}, #{planNodeId}, #{status}, #{attempt}, #{runnerType}, #{externalRunId},
    #{errorCode}, #{errorSummary}, cast(coalesce(#{resultSummaryJson}, '{}') as jsonb),
    #{heartbeatAt}, #{queuedAt}, #{startedAt}, #{finishedAt}, #{createdAt}, #{updatedAt}
)

insert into execution_queue_claim (
    id, node_run_id, claim_token, worker_id, claimed_at, heartbeat_at,
    expires_at, status, created_at, updated_at
) values (
    #{id}, #{nodeRunId}, #{claimToken}, #{workerId}, #{claimedAt}, #{heartbeatAt},
    #{expiresAt}, #{status}, #{createdAt}, #{updatedAt}
)
on conflict do nothing

insert into execution_trigger (
    id, plan_id, trigger_type, status, config_digest, config_summary_json,
    secret_ref, secret_ref_digest, next_fire_at, last_fire_at,
    created_by, updated_by, created_at, updated_at
) values (
    #{id}, #{planId}, #{triggerType}, #{status}, #{configDigest},
    cast(coalesce(#{configSummaryJson}, '{}') as jsonb),
    #{secretRef}, #{secretRefDigest}, #{nextFireAt}, #{lastFireAt},
    #{createdBy}, #{updatedBy}, #{createdAt}, #{updatedAt}
)

insert into execution_trigger_event (
    id, trigger_id, source_event_id, request_digest, status, run_id,
    received_at, error_code, error_summary, trace_id
) values (
    #{id}, #{triggerId}, #{sourceEventId}, #{requestDigest}, #{status}, #{runId},
    #{receivedAt}, #{errorCode}, #{errorSummary}, #{traceId}
)
on conflict do nothing

mapper.update:
update execution_queue_claim set
    heartbeat_at = #{heartbeatAt},
    expires_at = #{expiresAt},
    status = #{status},
    updated_at = #{updatedAt}
where id = #{id}

update execution_queue_claim set
    heartbeat_at = #{claim.heartbeatAt},
    expires_at = #{claim.expiresAt},
    status = #{claim.status},
    updated_at = #{claim.updatedAt}
where id = #{claim.id}
  and status = #{expectedStatus}

update execution_queue_claim set
    heartbeat_at = #{claim.heartbeatAt},
    expires_at = #{claim.expiresAt},
    status = #{claim.status},
    updated_at = #{claim.updatedAt}
where id = #{claim.id}
  and status = 'CLAIMED'
  and expires_at <= #{referenceTime}

mapper.select:
select 
from execution_plan
where id = #{id}

select project_id
from execution_plan
where id = #{id}

select 
from execution_run
where id = #{id}

select 
from execution_node_run nr
where nr.id = #{id}

select 
from execution_run
where plan_id = #{planId}
  and request_key = #{requestKey}
limit 1

select 
from execution_queue_claim
where status = 'CLAIMED'
  and expires_at <= #{now}
order by expires_at asc, claimed_at asc
limit #{limit}

select project_id
from execution_run
where id = #{id}

select 
from execution_trigger
where id = #{id}

select 
from execution_trigger_event
where id = #{id}

select 
from execution_trigger_event
where trigger_id = #{triggerId}
  and source_event_id = #{sourceEventId}
limit 1
